105	/* Liang-Barsky clip of the segment to [0,w-1]x[0,h-1]; false if outside. */
106	static int clip_line(const Canvas *c, double *x0, double *y0, double *x1,
107	                     double *y1) {
108	  double dx = *x1 - *x0, dy = *y1 - *y0, t0 = 0, t1 = 1;
109	  double p[4] = {-dx, dx, -dy, dy};
110	  double q[4] = {*x0, (c->w - 1) - *x0, *y0, (c->h - 1) - *y0};
111	  for (int i = 0; i < 4; i++) {
112	    if (p[i] == 0) {
113	      if (q[i] < 0) return 0;
114	    } else {
115	      double t = q[i] / p[i];
116	      if (p[i] < 0) {
117	        if (t > t1) return 0;
118	        if (t > t0) t0 = t;
119	      } else {
120	        if (t < t0) return 0;
121	        if (t < t1) t1 = t;
122	      }
123	    }
124	  }
125	  double ax = *x0, ay = *y0;
126	  *x0 = ax + t0 * dx;
127	  *y0 = ay + t0 * dy;
128	  *x1 = ax + t1 * dx;
129	  *y1 = ay + t1 * dy;
130	  return 1;
131	}
