133	void canvas_line(Canvas *c, int x0, int y0, int x1, int y1, uint16_t color) {
134	  double ax = x0, ay = y0, bx = x1, by = y1;
135	  int clipped = x0 < 0 || y0 < 0 || x0 >= c->w || y0 >= c->h || x1 < 0 ||
136	                y1 < 0 || x1 >= c->w || y1 >= c->h;
137	  if (clipped) {
138	    if (!clip_line(c, &ax, &ay, &bx, &by)) return;
139	    ax = floor(ax + 0.5);
140	    ay = floor(ay + 0.5);
141	    bx = floor(bx + 0.5);
142	    by = floor(by + 0.5);
143	  }
144	  int ix0 = (int)ax, iy0 = (int)ay, ix1 = (int)bx, iy1 = (int)by;
145	  int dx = abs(ix1 - ix0), sx = ix0 < ix1 ? 1 : -1;
146	  int dy = -abs(iy1 - iy0), sy = iy0 < iy1 ? 1 : -1;
147	  int err = dx + dy;
148	  for (;;) {
149	    canvas_point(c, ix0, iy0, color);
150	    if (ix0 == ix1 && iy0 == iy1) break;
151	    int e2 = 2 * err;
152	    if (e2 >= dy) {
153	      err += dy;
154	      ix0 += sx;
155	    }
156	    if (e2 <= dx) {
157	      err += dx;
158	      iy0 += sy;
159	    }
160	  }
161	}
