163	void canvas_fill_ellipse(Canvas *c, int x, int y, int w, int h,
164	                         uint16_t color) {
165	  if (w <= 0 || h <= 0) return;
166	  double cx = x + (w - 1) / 2.0, cy = y + (h - 1) / 2.0;
167	  double rx = w / 2.0, ry = h / 2.0;
168	  wide_t y0 = y < 0 ? 0 : y, y1 = (wide_t)y + h - 1;
169	  if (y1 >= c->h) y1 = c->h - 1;
170	  for (wide_t yy = y0; yy <= y1; yy++) {
171	    double ny = (yy - cy) / ry;
172	    double t = 1.0 - ny * ny;
173	    if (t < 0) continue;
174	    double half = rx * sqrt(t);
175	    wide_t xa = (wide_t)ceil(cx - half), xb = (wide_t)floor(cx + half);
176	    if (xb < xa) continue;
177	    hspan(c, xa, xb, yy, color);
178	  }
179	}
