    return;
  }
  if (!g_disc_built[w]) build_disc(w);
  for (int row = 0; row < w; row++) {
    const disc_row d = g_disc_rows[w][row];
    if (d.xb >= d.xa) fill_box(c, x + d.xa, y + row, x + d.xb, y + row, colour);
  }
}

